import json
with open('/app/resources/treasury_bulletin_1960_01.json') as f:
    data = json.load(f)
# Look for tables with 'exchange' or 'rate' or 'canadian'
def search(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if any(x in k.lower() for x in ['exchange', 'rate', 'canadian', 'cad']):
                print(f'{path}.{k}: {str(v)[:200]}')
            search(v, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            search(v, f'{path}[{i}]')
search(data)
